questions.text:
Observe el objeto. ¿Qué valor se muestra en consola?

let estudiante = {
    nombre: "Ana",
    edad: 19,
    carrera: "Software"
};

console.log(estudiante.carrera);

En el siguiente ejemplo de composición, ¿qué valor imprime el programa?

let persona = {
    nombre: "Carlos",
    direccion: {
        ciudad: "Quito",
        sector: "Tumbaco"
    }
};

console.log(persona.direccion.ciudad);

¿Qué valor queda almacenado en producto.fabricante.pais al finalizar el código?

let producto = {
    nombre: "Laptop",
    fabricante: {
        nombre: "TechCorp",
        pais: "Ecuador"
    }
};

producto.fabricante.pais = "Colombia";

¿Qué se muestra en consola?

let curso = {
    nombre: "Algoritmos",
    estudiantes: [
        { nombre: "María" },
        { nombre: "Luis" }
    ]
};

console.log(curso.estudiantes[1].nombre);

¿Qué valor se imprime en consola?

let numeros = [10, 20, 30, 40];

console.log(numeros[2]);

Después de ejecutar el código, ¿qué valor tiene colores[1]?

let colores = ["rojo", "azul", "verde"];

colores[1] = "amarillo";

¿Qué valor imprime console.log(numeros.length)?

let numeros = [10, 20, 30, 40];

numeros.push(50);

console.log(numeros.length);

¿Qué valor queda almacenado en la variable ultimo?

let datos = [5, 10, 15];

let ultimo = datos.pop();

¿Cuál es el valor final de suma?

let numeros = [1, 2, 3, 4];
let suma = 0;

for (let i = 0; i < numeros.length; i++) {
    suma = suma + numeros[i];
}

¿Qué imprime el siguiente código?

let nombres = ["Ana", "Luis", "Pedro"];

console.log(nombres[nombres.length - 1]);

¿Qué se muestra en consola?

let estudiantes = new Map();

estudiantes.set("A01", "Carlos");
estudiantes.set("A02", "María");

console.log(estudiantes.get("A02"));

¿Qué valor se obtiene con edades.get('Ana')?

let edades = new Map();

edades.set("Ana", 20);
edades.set("Ana", 21);

console.log(edades.get("Ana"));

¿Qué imprime el siguiente código?

let usuarios = new Map();

usuarios.set("A01", "Carlos");
usuarios.set("A02", "María");

console.log(usuarios.has("A03"));

¿Qué valor se muestra en consola?

let pila = [];

pila.push("A");
pila.push("B");
pila.push("C");

let elemento = pila.pop();

console.log(elemento);

Después de ejecutar dos operaciones pop(), ¿qué valor queda en la parte superior de la pila?

let pila = [];

pila.push(10);
pila.push(20);
pila.push(30);

pila.pop();
pila.pop();

¿Qué valor se muestra en consola?

let cola = [];

cola.push("Cliente 1");
cola.push("Cliente 2");
cola.push("Cliente 3");

let atendido = cola.shift();

console.log(atendido);

¿Qué valor final queda almacenado en mayor?

let numeros = [4, 8, 2, 10, 3];
let mayor = numeros[0];

for (let i = 1; i < numeros.length; i++) {
    if (numeros[i] > mayor) {
        mayor = numeros[i];
    }
}

¿Cuál es el valor final de contador?

let numeros = [2, 5, 8, 11, 14];
let contador = 0;

for (let i = 0; i < numeros.length; i++) {
    if (numeros[i] % 2 === 0) {
        contador++;
    }
}

¿Qué imprime el algoritmo de búsqueda?

let datos = [12, 7, 25, 9];
let buscado = 25;
let posicion = -1;

for (let i = 0; i < datos.length; i++) {
    if (datos[i] === buscado) {
        posicion = i;
        break;
    }
}

console.log(posicion);

¿Cuál es el valor final de total?

let valores = [3, 6, 9];
let total = 0;

for (let i = 0; i < valores.length; i++) {
    total += valores[i];
}

¿Qué se mostrará en consola al usar una pila para invertir el orden?

let pila = [];
let letras = ["A", "B", "C"];

for (let i = 0; i < letras.length; i++) {
    pila.push(letras[i]);
}

let resultado = "";

while (pila.length > 0) {
    resultado += pila.pop() + " ";
}

console.log(resultado.trim());

¿Qué valor imprime el siguiente algoritmo?

let numeros = [7, 3, 9, 4];
let menor = numeros[0];

for (let i = 1; i < numeros.length; i++) {
    if (numeros[i] < menor) {
        menor = numeros[i];
    }
}

console.log(menor);
